55: template <typename PixelType>
56: void compareToReference(
57:   const Image& image,
58:   const std::filesystem::path& refFilePath,
59:   int margin = 0)
60: {
61:   auto refImg = netpbm::read<PixelType>(refFilePath.string());
62:   const int channels = netpbm::is_rgb_v<PixelType> ? 3 : 1;
63:   const int bitDepth = 8 * sizeof(PixelType) / channels;
64:   REQUIRE (image.width == refImg.width);
65:   REQUIRE (image.height == refImg.height);
66:   REQUIRE (image.channels == channels);
67:   REQUIRE (image.bitDepth == bitDepth);
68:   REQUIRE (image.dataSize() == channels * refImg.width * refImg.height * (bitDepth / 8));
69:   REQUIRE (image.dataSize<PixelType>() == refImg.pixels.size());
70:   REQUIRE (image.dataPtr() != nullptr);
71:   if constexpr (netpbm::is_rgb_v<PixelType>) {
72:     using T = typename PixelType::value_type;
73:     const auto* pixels = image.dataPtr<T>();
74:     const auto* refPixels = refImg.pixels.data();
75:     for (size_t h = 0; h < image.height; ++h) {
76:       const auto* row = pixels + h * image.rowStride / sizeof(T);
77:       const auto* refRow = refPixels + h * refImg.width;
78:       for (size_t col = 0; col < image.width; ++col) {
79:         const auto* pixel = row + col * image.colStride / sizeof(T);
80:         const auto red = pixel[0 * image.chanStride / sizeof(T)];
81:         const auto green = pixel[1 * image.chanStride / sizeof(T)];
82:         const auto blue = pixel[2 * image.chanStride / sizeof(T)];
83:         REQUIRE (std::abs(double(refRow[col].r) - red) <= margin);
84:         REQUIRE (std::abs(double(refRow[col].g) - green) <= margin);
85:         REQUIRE (std::abs(double(refRow[col].b) - blue) <= margin);
86:       }
87:     }
88:   } else if constexpr (std::is_same_v<PixelType, bool>) {
89:     const uint8_t* pixels = image.dataPtr<uint8_t>();
90:     for (size_t h = 0; h < image.height; ++h) {
91:       const uint8_t* row = pixels + h * image.rowStride / sizeof(uint8_t);
92:       for (size_t col = 0; col < image.width; ++col) {
93:         const uint8_t* pixel = row + col * image.colStride / sizeof(uint8_t);
94:         const int refPixel = refImg.pixels[h * refImg.width + col] ? 0x00 : 0xff; // false = white, true = black
95:         REQUIRE (refPixel == *pixel);
